 public string BuyFilamentP(int id){if(!Docked||Balance<400||!FilamentsP.All.Any(f=>f.Id==id))return "Dock with 400 CR and choose a source filament.";string key=StationKey44+":"+id;int stock=OperationsP.FilamentStock.GetValueOrDefault(key,3);if(stock<=0)return "Finite local filament stock depleted.";OperationsP.FilamentStock[key]=stock-1;WalletChange(-400,"Regional physical filament");Hangar["sde_"+id]=Hangar.GetValueOrDefault("sde_"+id)+1;return "";}
