 public void TickFilamentP(){var s=OperationsP.Transit;if(s==null)return;var f=FilamentsP.All.First(x=>x.Id==s.Filament);if(Docked||SystemId!=s.From||Grid!=s.Grid||InWarp||Commander.Capsule||Player.Hull<=0||WarpBlocked("player")||(SystemPosition-s.Position).Length>f.Radius||s.Crew.Any(id=>PopulationPilot(id) is not {Contracted:true,Suspended:false,Status:"Fleet",Fit.Hull:>0} p||p.System!=SystemId||p.Grid!=Grid||Vector3.Distance(p.Position,Player.Position)>f.Radius||WarpBlocked(id))){OperationsP.Transit=null;Say("Regional spool failed; physical filament remains spent.");return;}if(Now<s.Ends)return;OperationsP.Transit=null;SyncEncounterF();RecoverProbesForTransit();LeaveSupportGrid(true);SystemId=s.Destination;EnterGrid("station",false);Player.Position=Vector3.Zero;Player.Velocity=Vector3.Zero;foreach(string id in s.Crew){var p=PopulationPilot(id)!;p.System=SystemId;p.Grid=Grid;}BindPopulationGridC();Say("Regional filament transit complete.");}
